        (, uint balBefore) = c.Acc(address(this));
        uint cbalBefore = address(c).balance;
        uint myBefore = address(this).balance;

        c.Collect(am);

        (, uint balAfter) = c.Acc(address(this));
        uint cbalAfter = address(c).balance;
        uint myAfter = address(this).balance;

        assert(balAfter == balBefore - am
            && cbalAfter == cbalBefore - am
            && myAfter == myBefore + am);
    }

    receive() external payable {}
}

